import{_ as t}from"./chunks/screenshot.WF6E8Lhn.js";import{_ as o,o as r,c as a,ae as i}from"./chunks/framework.8rYXDNLJ.js";const g=JSON.parse('{"title":"What is Portman?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-portman.md","filePath":"guide/what-is-portman.md"}'),s={name:"guide/what-is-portman.md"};function n(l,e,p,h,c,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="what-is-portman" tabindex="-1">What is Portman? <a class="header-anchor" href="#what-is-portman" aria-label="Permalink to &quot;What is Portman?&quot;">​</a></h1><p>Portman is a local port management tool designed specifically for macOS developers.</p><h2 id="the-problem" tabindex="-1">The Problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The Problem&quot;">​</a></h2><p>Modern development often involves running multiple services simultaneously:</p><ul><li>Frontend dev server (port 3000)</li><li>Backend API (port 8000)</li><li>Database (port 5432)</li><li>Redis (port 6379)</li><li>And more...</li></ul><p><strong>Port conflicts are inevitable.</strong> Especially when you&#39;re doing Vibe Coding with AI assistants that spin up new projects frequently, keeping track of what&#39;s running where becomes a challenge.</p><h2 id="the-solution" tabindex="-1">The Solution <a class="header-anchor" href="#the-solution" aria-label="Permalink to &quot;The Solution&quot;">​</a></h2><p>Portman gives you complete visibility into your local port usage:</p><p><img src="'+t+'" alt="Portman Active Ports"></p><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>Real-time scanning</strong> - See all active port listeners instantly</li><li><strong>Process detection</strong> - Know which process is using each port</li><li><strong>Custom labels</strong> - Tag ports with project names for easy identification</li><li><strong>Find free ports</strong> - Quickly discover available ports in any range</li><li><strong>MCP integration</strong> - Let AI assistants manage ports for you</li></ul><h2 id="who-is-it-for" tabindex="-1">Who is it for? <a class="header-anchor" href="#who-is-it-for" aria-label="Permalink to &quot;Who is it for?&quot;">​</a></h2><ul><li><strong>Web developers</strong> juggling multiple projects</li><li><strong>Full-stack developers</strong> running microservices locally</li><li><strong>AI-assisted coders</strong> using Claude, Cursor, or similar tools</li><li><strong>Anyone</strong> who&#39;s ever wondered &quot;what&#39;s using port 3000?&quot;</li></ul><h2 id="desktop-app-mcp-server" tabindex="-1">Desktop App + MCP Server <a class="header-anchor" href="#desktop-app-mcp-server" aria-label="Permalink to &quot;Desktop App + MCP Server&quot;">​</a></h2><p>Portman comes in two flavors:</p><ol><li><strong>Desktop App</strong> - A native macOS app with a beautiful UI</li><li><strong>MCP Server</strong> - Connect to Claude Desktop/Code for AI-powered port management</li></ol><p>The Desktop app is free during beta (Proprietary EULA). The MCP server is MIT licensed.</p>',17)])])}const f=o(s,[["render",n]]);export{g as __pageData,f as default};
